import{describe,it,expect}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));describe("Nagapattinam Ancient Port Explorer Tests",()=>{it("HTML contains all required sections: historical overview, Chola maritime trade, cultural significance, timeline, gallery, and references",()=>{const t=readFileSync(resolve(__dirname,"../../nagapattinam-port-explorer/index.html"),"utf-8");expect(t).toContain('id="overview"'),expect(t).toContain('id="chola-maritime-trade"'),expect(t).toContain('id="cultural-significance"'),expect(t).toContain('id="timeline"'),expect(t).toContain('id="gallery"'),expect(t).toContain('id="references"'),expect(t).toContain("Nagapattinam"),expect(t).toContain("Chola"),expect(t).toContain("Srivijaya"),expect(t).toContain("Chudamani Vihara")}),it("CSS stylesheet exists and defines port styling tokens",()=>{const t=readFileSync(resolve(__dirname,"../../nagapattinam-port-explorer/style.css"),"utf-8");expect(t).toContain("--port-dark"),expect(t).toContain("--port-gold"),expect(t).toContain("--port-crimson"),expect(t).toContain(".port-main"),expect(t).toContain(".port-hero")}),it("JavaScript module initializes clean and registers search items",()=>{const t=readFileSync(resolve(__dirname,"../../nagapattinam-port-explorer/script.js"),"utf-8");expect(t).toContain("initNagapattinamPortExplorer"),expect(t).toContain("setupGalleryModal"),expect(t).toContain("nagapattinam-port-explorer/index.html")}),it("Landing Page Integration: Ancient Ports explorer landing page includes Nagapattinam card",()=>{const t=readFileSync(resolve(__dirname,"../../ancient-ports-explorer/index.html"),"utf-8");expect(t).toContain("Nagapattinam Ancient Port"),expect(t).toContain("../nagapattinam-port-explorer/index.html")})});